import{z as s,x as A,o as i,c as p,q as t,j as B,D as e,d as l,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"吸收体材料","description":"","frontmatter":{"title":"吸收体材料","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-absorber-materials.md","filePath":"litho/euv-absorber-materials.md","lastUpdated":1791063341000}'),d={name:"litho/euv-absorber-materials.md"};function h(D,a,m,k,u,N){const r=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="吸收体材料" tabindex="-1">吸收体材料 <a class="header-anchor" href="#吸收体材料" aria-label="Permalink to &quot;吸收体材料&quot;">​</a></h1><div class="epigraph"><p>EUV 版的对比来自吸收体挡住该反射的光；材料的 n、k 和厚度决定阴影、相位和能不能减薄。</p><footer>—— 对照 EUV 掩模公开材料中的 TaBN 系吸收体，以及 Ni 等后继吸收体讨论</footer></div><p><a href="/litho/euv-mask-defects">上一课</a>把空白版相位缺陷和吸收体振幅缺陷分开。缺口是：挡住光的那一层用什么。本课钉吸收体材料（公开的 TaBN 系，以及 Ni 等减薄方案）。光化检验如何看见它们，留给后课，不在这里写检测机台。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 掩模是反射多层加吸收体图形。吸收体必须在 13.5 nm 够暗，又要能被电子束写出、干法刻出、缺陷检出。厚度一旦到几十纳米，<a href="/litho/euv-oblique-shadow">斜入射阴影</a> 和三维掩模效应就把左右不对称、取向偏置写进空中像。<a href="/litho/opc">OPC</a> 可以修均值，但 MEF 和焦点窗跟吸收体的复折射率绑在一起。</p><p><span class="marginnote">术语翻译：复折射率 \\(n+ik\\) 里，\\(n\\) 管光「走多快」（相移），\\(k\\) 管「被吃掉多少」（吸收）。EUV 吸收体要 \\(k\\) 大才能薄而暗；但 \\(n\\) 不为零，厚度同时带来相移——所以减薄从来不是纯收益。</span></p><p>传统量产公开叙述以钽基为主：TaN / TaBN / TaBON 一类，刻蚀与检测链成熟。代价是要足够厚才压住反射，三维效应大。High-NA 角更大，同一厚度更不可接受。缺口是换材料或换厚度，而不是再讲一遍多层缺陷分类。</p><h3 id="k-高可以薄-但相位不是免费的" tabindex="-1">k 高可以薄，但相位不是免费的 <a class="header-anchor" href="#k-高可以薄-但相位不是免费的" aria-label="Permalink to &quot;k 高可以薄，但相位不是免费的&quot;">​</a></h3><p>吸收体不是纯振幅物体。n 偏离真空，厚度带来相移，侧壁和顶角进入严格电磁。减薄若只追光学密度，相位和侧壁会把 PV-band 做成新形状。材料表要同时看 k、n、蚀刻选择比和缺陷衬度。</p><p><span class="marginnote">直觉类比：挡光像挂窗帘——布料密（\\(k\\) 大）一层就够，稀疏纱帘要叠好几层（厚 TaBN）。可每叠一层，窗帘边缘投下的半影（三维阴影）就越宽；换高 \\(k\\) 材料就是换更遮光的布，把窗帘做薄。</span></p><p><span class="marginnote">DUV 铬/MoSi 的「薄吸收」直觉不能直接搬。EUV 是反射、斜入射；吸收体厚度走的是阴影预算，不是接近式光刻的胶厚类比。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>钽硼氮（TaBN）一类是公开的主流：硼调应力与微结构，氮调吸收和氧化，能在多层帽上刻出可用侧壁。检测在 DUV 与电子束下有衬度。缺点是光学常数决定了厚度下限，三维阴影成为 0.33 已必须进 OPC、0.55 更必须减薄或换高 k 的原因。</p><p>公开讨论的后继包括镍（Ni）等更高消光的金属：同样对比可用更薄的膜，阴影和 3D 效应下降。代价是刻蚀、缺陷、与多层的兼容、以及掩模厂工具链是否接得住。这是材料资格认证，不是 OPC 软件里改一个 n、k 表就完成迁移。</p><p><span class="marginnote">常见误区：以为换吸收体只是把模型里 \\(n\\)、\\(k\\) 两个数改掉。刻蚀气体、检测衬度、修复工艺、与多层帽的粘附和氢耐受都要重新资格认证——这是一条材料链的整体更换，不是软件里的一次查表更新。</span></p><h3 id="与变形倍率一起看" tabindex="-1">与变形倍率一起看 <a class="header-anchor" href="#与变形倍率一起看" aria-label="Permalink to &quot;与变形倍率一起看&quot;">​</a></h3><p><a href="/litho/anamorphic-projection">变形光学</a> 把掩模侧角度压回多层能活的窗。吸收体仍坐在这条光路上：薄而高 k 是给剩余入射角的余量。材料选择与倍率几何是同一张 High-NA 掩模预算的两边。</p>',17)),(i(),B(o,null,{default:e(()=>[n(r,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%80%99%E9%80%89%E5%90%B8%E6%94%B6%E4%BD%93%E6%9D%90%E6%96%99%22%5D%20--%3E%20O%5B%22%E5%85%89%E5%AD%A6%E5%85%B3%EF%BC%9A13.5%20nm%20%E5%A4%9F%E6%9A%97%E5%8F%AF%E5%87%8F%E8%96%84%22%5D%0A%20%20C%20--%3E%20P%5B%22%E7%9B%B8%E4%BD%8D%E5%85%B3%EF%BC%9An%20%E7%9B%B8%E7%A7%BB%E5%8F%AF%E8%BF%9B%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20C%20--%3E%20E%5B%22%E5%B7%A5%E8%89%BA%E5%85%B3%EF%BC%9A%E5%88%BB%E8%9A%80%E4%BE%A7%E5%A3%81%E4%B8%8E%E4%BF%AE%E5%A4%8D%22%5D%0A%20%20C%20--%3E%20D%5B%22%E6%A3%80%E6%B5%8B%E5%85%B3%EF%BC%9ADUV%20%E4%B8%8E%E7%94%B5%E5%AD%90%E6%9D%9F%E8%A1%AC%E5%BA%A6%22%5D%0A%20%20C%20--%3E%20H%5B%22%E5%85%BC%E5%AE%B9%E5%85%B3%EF%BC%9A%E5%A4%9A%E5%B1%82%E5%B8%BD%E4%B8%8E%E6%B0%A2%E8%80%90%E5%8F%97%22%5D%0A%20%20O%20--%3E%20Q%5B%22%E5%85%A8%E8%BF%87%20%E2%86%92%20%E6%8E%A9%E6%A8%A1%E5%8E%82%E8%B5%84%E6%A0%BC%E8%AE%A4%E8%AF%81%22%5D%0A%20%20P%20--%3E%20Q%0A%20%20E%20--%3E%20Q%0A%20%20D%20--%3E%20Q%0A%20%20H%20--%3E%20Q%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"空中像对比来自「该亮的多层」对「该暗的吸收体」的振幅差，再加三维电磁。侧壁不直、顶角倒角、底部残留，都会改有效相移。OPC 的掩模 3D 模型必须用当前材料校准；换 TaBN 到 Ni，等于作废旧紧凑掩模模型。",-1)),a[5]||(a[5]=E("p",null,"缺陷行为也随材料变。吸收体多一块、少一块的打印阈值取决于 k 和厚度；补偿修复（用图形盖相位坑）的工艺窗口同样绑在吸收体刻蚀上。上一课的缺陷分类在本课变成「这种材料上怎么修」。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"不要把实验室里某张 Ni 膜的 n、k 写成量产规格。公开事实是钽基在用、高 k / Ni 在讨论与导入路径上；节点资格以掩模厂与扫描机的公开叙述为准。")],-1)),(i(),B(o,null,{default:e(()=>[n(r,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20ML%5B%22Mo%2FSi%20%E7%A9%BA%E7%99%BD%E7%89%88%22%5D%20--%3E%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%E6%B2%89%E7%A7%AF%22%5D%0A%20%20ABS%20--%3E%20TA%5B%22TaBN%20%E7%B3%BB%3A%20%E6%88%90%E7%86%9F%E5%81%8F%E5%8E%9A%22%5D%0A%20%20ABS%20--%3E%20NI%5B%22Ni%20%E7%AD%89%E9%AB%98%20k%3A%20%E5%8F%AF%E5%87%8F%E8%96%84%22%5D%0A%20%20TA%20--%3E%20SH%5B%22%E4%B8%89%E7%BB%B4%E9%98%B4%E5%BD%B1%20%2F%20%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20NI%20--%3E%20SH%0A%20%20SH%20--%3E%20OPC%5B%22%E6%8E%A9%E6%A8%A1%203D%20OPC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写埋藏相位坑，也不给具体膜厚纳米数当出厂值。不要发明某代 EXE 已经切换到某牌镍吸收体。后课默认：说到 EUV 版图形层，先问是钽基还是后继高 k，再谈阴影模型。</p><p>引用停在掩模公开文献与 ASML / 产业对吸收体的公开讨论。</p><p><span class="marginnote">吸收体不是 pellicle。pellicle 挡颗粒、贡献透过率；吸收体画电路。氢损伤两条链也不要并成一种「膜」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>量产 EUV 吸收体公开主流是 TaBN 系；厚度换来对比，也换来三维阴影。</li><li>Ni 等高 k 材料的公开动机是减薄、压 3D 效应，尤其服务更大掩模角。</li><li>n、k、侧壁一起进空中像；换材料等于重校准掩模 3D OPC。</li><li>缺陷修复工艺与吸收体刻蚀链绑定。</li><li>出处：EUV 掩模公开文献；TaBN / Ni 等吸收体的产业公开讨论。</li></ul>',6))])}const T=s(d,[["render",h]]);export{f as __pageData,T as default};
